        // Yashirin varaq/qatorlar (Excel «скрыть»): .xlsx (XML) va .xls (BIFF8)
        function narHidden(bs, fname) {
            const out = { sheets: {}, rows: {} };
            try {
                if (/\.xls$/i.test(fname) || bs.charCodeAt(0) === 0xD0) {
                    const cfb = XLSX.CFB.read(bs, { type: 'binary' });
                    const ent = cfb.find('Workbook') || cfb.find('Book'); if (!ent) return out;
                    const d = ent.content, n = d.length, u8 = i => d[i] & 255, u16 = i => u8(i) | (u8(i + 1) << 8), u32 = i => (u16(i) | (u16(i + 2) << 16)) >>> 0;
                    const bsh = []; let p = 0, cur = null;
                    while (p + 4 <= n) {
                        const t = u16(p), l = u16(p + 2), b = p + 4;
                        if (t === 0x0085 && l >= 8) { const pos = u32(b), st = u8(b + 4) & 3, cch = u8(b + 6), hb = u8(b + 7) & 1; let s = ''; for (let k = 0; k < cch; k++) s += hb ? String.fromCharCode(u16(b + 8 + k * 2)) : String.fromCharCode(u8(b + 8 + k)); bsh.push({ pos: pos, st: st, name: s }); out.sheets[s] = st > 0; }
                        else if (t === 0x0809) { const sh = bsh.find(z => z.pos === p); if (sh) cur = sh.name; }
                        else if (t === 0x0208 && cur && l >= 16) { if (u16(b + 12) & 0x20) (out.rows[cur] = out.rows[cur] || []).push(u16(b) + 1); }
                        p = b + l;
                    }
                } else {
                    const z = new JSZip(bs), rd = f => { const e = z.file(f); return e ? e.asText() : ''; };
                    const wbx = rd('xl/workbook.xml'), rel = rd('xl/_rels/workbook.xml.rels'), rm = {};
                    rel.replace(/<Relationship\b[^>]*>/g, m => { const id = (m.match(/\bId="([^"]+)"/) || [])[1], tg = (m.match(/\bTarget="([^"]+)"/) || [])[1]; if (id && tg) rm[id] = tg.replace(/^\/?(xl\/)?/, 'xl/'); return m; });
                    const ent = s => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&#(\d+);/g, (m, k) => String.fromCharCode(+k));
                    wbx.replace(/<sheet\b[^>]*>/g, m => {
                        const nm = ent((m.match(/\bname="([^"]*)"/) || [])[1] || ''), st = (m.match(/\bstate="([^"]*)"/) || [])[1] || '', id = (m.match(/\br:id="([^"]+)"/) || [])[1];
                        out.sheets[nm] = /hidden/i.test(st);
                        const x = id && rm[id] ? rd(rm[id]) : ''; const H = [];
                        x.replace(/<row\b[^>]*>/g, r => { if (/\bhidden="(1|true)"/.test(r)) { const rr = (r.match(/\br="(\d+)"/) || [])[1]; if (rr) H.push(+rr); } return r; });
                        if (H.length) out.rows[nm] = H; return m;
                    });
                }
            } catch (e) { out.err = String(e && e.message || e); }
            return out;
        }

        // ---------- Ichki (tayyor) normalar bazasi ----------
        function narSeedDB() {
            const S = typeof NAR_SEED !== 'undefined' ? NAR_SEED : { sets: [], tariffs: [] };
            return { v: 1, seed: S.v || 1, sets: S.sets.map(z => ({ id: 'ns_' + z.c, code: z.c, title: z.t, k: z.k, file: z.f || '', sheet: z.sh || '', date: z.d, total: { nt: z.tot }, items: z.i.map(a => ({ no: a[0], name: a[1], unit: a[2], raz: a[3], nt: a[4] })), builtin: 1 })), tariffs: S.tariffs.map(t => ({ from: t.from, r: Object.assign({}, t.r), src: 'Tasdiqlangan normalar hujjatlari' })), log: [] };
        }

        // ---------- 5) Ilova: bo'limlar va ekranlar ----------
        //  Buxgalteriya va Iqtisodiyot → 💰 Buxgalteriya (oldingi ekran) | 📈 Iqtisodiyot → 👷 Mehnatni tashkil etish va ish haqi
        var NAR_WAG_KEY = 'agmk_nar_wag_v1';
        var NAR = { tab: 'chk', chk: null, data: null, f: 'all', q: '', nq: '', wq: '', _db: null };
        try { if (typeof ROLE_DEF !== 'undefined' && !ROLE_DEF.some(r => r[0] === 'mtih')) ROLE_DEF.push(['mtih', '👷', 'Mehnatni tashkil etish va ish haqi', 'Naryadlarni tekshiradi, ish normalari va tarif stavkalarini yuritadi']); } catch (e) {}
        function narCan() { try { return isAdmin() || hasRole('mtih') || hasRole('bux') || hasRole('rahbar'); } catch (e) { return false; } }
        function narCanEdit() { try { return isAdmin() || hasRole('mtih'); } catch (e) { return false; } }
        function narDB() { if (NAR._db) return NAR._db; const d = kvGet(NAR_KEY, null); NAR._db = d && d.sets && d.sets.length ? d : narSeedDB(); return NAR._db; }
        function narSaveDB(d) { const c = JSON.parse(JSON.stringify(d, (k, v) => k === 'toks' ? undefined : v)); kvSet(NAR_KEY, c); NAR._db = null; }
        function narChecks() { const l = kvGet(NAR_CHK_KEY, []); return Array.isArray(l) ? l : []; }
        function narRec(id) { return narChecks().find(x => x.id === id) || null; }
        function narLedger() { const l = kvGet(NAR_WAG_KEY, {}); return l && typeof l === 'object' ? l : {}; }
        function narLedgerDrop(L, fid) { Object.keys(L).forEach(k => { L[k] = (L[k] || []).filter(z => z.file !== fid); if (!L[k].length) delete L[k]; }); return L; }
        function narPer(p) { if (!p) return '—'; const M = ['yanvar', 'fevral', 'mart', 'aprel', 'may', 'iyun', 'iyul', 'avgust', 'sentyabr', 'oktyabr', 'noyabr', 'dekabr']; return p.slice(0, 4) + '-yil ' + (M[+p.slice(5, 7) - 1] || p.slice(5)); }
        function narDmy(d) { return d ? d.split('-').reverse().join('.') : ''; }
        function narCard(ic, t, sub, on, extra) { return `<div class="btn-card nar-card${extra ? ' ' + extra : ''}" onclick="${on}"><div class="btn-card-content"><span class="btn-icon">${ic}</span><span class="btn-text">${escapeHtml(t)}<small>${escapeHtml(sub)}</small></span></div><span class="btn-arrow">›</span></div>`; }
